package os.aios.agent;
import android.app.*;import android.content.*;import android.os.*;import android.database.Cursor;import android.provider.ContactsContract;import org.json.*;import java.util.*;
public final class ContactsVirtualProbe extends Instrumentation {
 AgentService service;String thread;JSONObject original;ArrayList<String> own=new ArrayList<>();JSONArray log=new JSONArray();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 JSONObject call(JSONObject q)throws Exception{UiSessionManager.caller.set(thread);try{return service.ui.call(q);}finally{UiSessionManager.caller.remove();}}
 JSONArray devices()throws Exception{Object mgr=getTargetContext().getSystemService("virtualdevice");JSONArray a=new JSONArray();if(mgr==null)return a.put("null manager");for(Object d:(java.util.List<?>)mgr.getClass().getMethod("getVirtualDevices").invoke(mgr)){int id=(Integer)d.getClass().getMethod("getDeviceId").invoke(d);JSONObject j=new JSONObject().put("id",id);try{getTargetContext().createDeviceContext(id);j.put("context","valid");}catch(Exception ex){j.put("context",ex.toString());}a.put(j);}return a;}
 void allowOnce(){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).getRootInActiveWindow();if(root==null||!"com.android.virtualdevicemanager".contentEquals(root.getPackageName()))return;for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("仅限这一次")){for(int i=0;i<3&&n!=null;i++,n=n.getParent())if(n.isClickable()){n.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);return;}}}
 void query(Context c,String label)throws Exception{JSONObject j=new JSONObject().put("query",label).put("device",c.getDeviceId());try(Cursor cursor=c.getContentResolver().query(ContactsContract.ProviderStatus.CONTENT_URI,new String[]{ContactsContract.ProviderStatus.STATUS},null,null,null)){j.put("ok",cursor!=null);}catch(Exception ex){j.put("error",android.util.Log.getStackTraceString(ex));}log.put(j);}
 public void onStart(){Bundle out=new Bundle();int code=-1;try{
 Context c=getTargetContext();c.startForegroundService(new Intent(c,AgentService.class));for(int i=0;i<40&&AgentService.instance==null;i++)Thread.sleep(200);service=AgentService.instance;if(service==null)throw new AssertionError("service missing");original=AssistantConversation.state(c);thread=original.getString("thread_id");JSONObject state=new JSONObject(original.toString()).put("request_id",UUID.randomUUID().toString()).put("ui_origin",new JSONObject().put("assistant_package","com.android.launcher3").put("virtual_session",""));c.getSharedPreferences("assistant_conversation",0).edit().putString("state",state.toString()).commit();
 log.put(new JSONObject().put("before",devices()));query(c,"main-before");
 for(String pkg:new String[]{"com.android.deskclock","com.android.contacts"}){JSONObject created=call(new JSONObject().put("op","create").put("package",pkg).put("mode","background"));String id=created.optString("session_id");if(!id.isEmpty())own.add(id);log.put(new JSONObject().put("created_package",pkg).put("session",created).put("devices",devices()));
 for(int wait=0;wait<120;wait++){allowOnce();JSONObject status=call(new JSONObject().put("op","status").put("session_id",id));if(status.optString("state").equals("active"))break;if(wait==119)throw new AssertionError("session never active: "+status);Thread.sleep(500);}
 for(int i=0;i<5;i++){Thread.sleep(1000);if(!"active".equals(call(new JSONObject().put("op","status").put("session_id",id)).optString("state")))throw new AssertionError("Virtual session disappeared: "+pkg);log.put(new JSONObject().put("package",pkg).put("second",i+1).put("status",call(new JSONObject().put("op","status").put("session_id",id))).put("devices",devices()));}
 }
 JSONArray ds=devices();for(int i=0;i<ds.length();i++){JSONObject d=ds.optJSONObject(i);if(d!=null)query(c.createDeviceContext(d.getInt("id")),"live-virtual-query");}query(c,"main-after");
 }catch(Throwable ex){code=0;log.put(android.util.Log.getStackTraceString(ex));}finally{if(service!=null)for(String id:own)try{JSONObject closed=call(new JSONObject().put("op","close").put("session_id",id));log.put(new JSONObject().put("closed_session",id).put("result",closed));if(!"closed".equals(closed.optString("state"))&&!"session_not_found".equals(closed.optString("state")))code=0;Thread.sleep(600);}catch(Exception cleanup){code=0;log.put("cleanup: "+cleanup);}if(original!=null)getTargetContext().getSharedPreferences("assistant_conversation",0).edit().putString("state",original.toString()).commit();out.putString("stream",log.toString());finish(code,out);}
 }
}
